const todoSections={
 'local-area':['Local Area','Explore Ballymoney, Gorey and the Wexford coastline.'],
 transport:['Local Transport','Local Bus: McGoverns Main St to Hughes Ballymoney, 5 mins, €5. Gorey Bus Links: http://www.goreybuslinks.ie/. Taxi Paddy: 0879502031; Chris Bolton: 0876009785. Travel from Dublin by Irish Rail to Gorey or Wexford Bus from Leeson Street.'],
 'walks-trails-greenways':['Beaches, Walks, Trails & Greenways','Walk maps: https://wexfordwalkingtrail.ie/trails-maps/. Four beaches are within five minutes’ drive. Local favourites include Sea Road Ballymoney North, Kiltennel Beach & Forest Walk and Courtown Harbour. Curracloe is around 20 minutes away. Courtown to Ballymoney Loop is 22km.'],
 'take-aways':['Take Aways','A wide range of take-aways is available in Gorey. Orphan Girl Chipper: (053) 942 5308; open weekends in winter and daily in summer from 5pm. Just Eat has current delivery choices. Our favourite Indian is Masala House; our favourite Chinese is Ipho.'],
 'outdoor-activities':['Outdoor Activities','The gated community has two tennis courts, football and five-a-side pitches, playgrounds, The Shed, Kids Play, dog playground and pedal-kart/bicycle track. Tara Meadows Summer Camp runs in July and August. Active Tribe in Courtown offers swimming, gym, archery, laser tag, woodland walks, high ropes, climbing and zip line.'],
 'indoor-activities':['Indoor Activities','Pirates Cove offers bowling and arcades. Movies @ Gorey is nine minutes away. Family options include Kid Zone, Courtown Adventure & Leisure Centre, Amber Springs and Active Tribe classes.'],
 'swimming-pools':['Swimming Pools','<a href="https://www.activetribe.ie/" target="_blank" rel="noreferrer">Active Tribe</a> offers swimming in Courtown. Other options include Courtown Leisure Centre (nine minutes by car), <a href="https://www.ambersprings.ie/swimming.html" target="_blank" rel="noreferrer">Amber Springs</a> (ten minutes), <a href="https://oceospa.onejourney.travel/" target="_blank" rel="noreferrer">Oceo Spa at Seafield Spa & Resort</a> (adults only; four minutes) and <a href="https://www.ashdownparkhotel.com/swim.html" target="_blank" rel="noreferrer">Ashdown Park Hotel & Leisure Club</a> (seven minutes).'],
 'farms-petting-zoos':['Farms & Petting Zoos','Kia Ora Mini Farm is nine minutes away. Amber Springs includes a petting zoo. Alpaca Lodge offers alpaca feeding and walks. Wexford Lavender Farm has a café, gift shop, playground and woodland walks.'],
 'local-markets-shopping':['Local Markets & Shopping','Gorey Farmers Market: Saturdays 9am–2pm, Esmonde Street. Samhradh Market: Wednesdays 10am to 1pm at The Orphan Girl, seasonal, mid June to late August. Hughes Londis on Ballymoney Road, opposite Sea Road, is our closest shop. The Orphan Girl is planning to open a convenience store in late 2026. Larger supermarkets including Aldi, Lidl, Polone’s, Dunnes and Tesco are a 10-minute drive away in Gorey Town Centre.'],
 'local-pubs-restaurants':['Local Pubs, Restaurants & Dog Friendly','The Orphan Girl is our closest pub, an eight-minute walk, known for steaks, music and summer outdoor dining. Tara Vale is six minutes by car. Favourites include Seafield’s Clubhouse, The Duck at Marlfield House and Springmount.'],
 'estate-homes-gardens':['Estate Homes & Gardens','Wells House & Gardens has 450 acres of woodland, gardens, fairy and Gruffalo walks, animal farm and playground. Marlfield House & Gardens and The Duck Restaurant are eight minutes away.'],
 golf:['Golf','Ballymoney Golf Club: 053 94 21976 · info@ballymoneygolfclub.ie · http://www.ballymoneygolfclub.ie/. Other local clubs include Tara Glen and Courtown Golf Club.'],
 courtown:['Courtown','Courtown is a ten-minute drive away. Enjoy the amusement park, Pirates Cove, bowling, arcades, soft play, boat rides, train rides, go-karts, woodland trails and harbour walks.'],
 'local-spas':['Local Spas','Seafield Hotel & Spa (adults only), Amber Springs Hotel & Spa and Ashdown Park Hotel all have excellent spa or leisure facilities. Gorey also has several Thai massage options. For a sauna experience nearby, visit <a href="https://sybilssauna.ie/" target="_blank" rel="noreferrer">Sybil’s Sauna</a>.'],
 'our-favorite-places':['Our Favorite Places','Orphan Girl for Guinness, steak and stone-baked pizzas; Joannes for bread; Salt Rock Dairy for milk and ice cream; Gorey Farmers Market for local produce; and Rowantree Restaurant at Ashdown Park Hotel.']
};
