  modern:{name:'Modern',eyebrow:'BALLYMONEY · GOREY · WEXFORD',headline:'Beach days, slow mornings, room for everyone.',intro:'A bright, family-friendly coastal escape with four bedrooms, a private hot tub and the best of North Wexford on your doorstep.',hero:'/images/nearby-ballymoney-beach.webp',accent:'A relaxed, editorial style with clean space, easy booking and warm coastal colour.'},
  luxury:{name:'Luxury',eyebrow:'COUNTRY BEACH ESCAPE',headline:'A private coastal retreat, thoughtfully yours.',intro:'Four beautifully considered bedrooms, an outdoor hot tub and an easy, unhurried escape near Ballymoney Beach.',hero:'/images/outdoor-patio-hot-tub.jpg',accent:'A quiet, premium look using dramatic photography, elegant type and rich, considered detail.'},
